import base64
from Crypto.Cipher import AES
import hashlib

def nth_root(n, a):
    low = 0
    high = a
    while low <= high:
        mid = (low + high) // 2
        if mid == 0:
            low = 1
            continue
        p = pow(mid, n)
        if p == a:
            return mid
        elif p < a:
            low = mid + 1
        else:
            high = mid - 1
    return low

